create temp table w116k_map (id int, jd_url text, jd_name text, resp jsonb) on commit drop;
update public.team_members m set jd_url = v.jd_url, jd_name = v.jd_name
from w116k_map v where m.id = v.id and m.jd_url is null and v.jd_url is not null;
update public.team_members m set responsibilities = v.resp
from w116k_map v where m.id = v.id and (m.responsibilities is null or jsonb_typeof(m.responsibilities) <> 'array' or jsonb_array_length(m.responsibilities) = 0);
select 'team_member', v.id::text, 'job_description', 'none', coalesce(v.jd_name, 'responsibilities only'), 'hub (wave116k, HR shared drive job descriptions)' from w116k_map v;
